/// Actions available to each state in the security game.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum Action {
    /// Build up military capability (arms race move).
    Arm,
    /// Offer arms-control concession.
    Concede,
    /// Probe with limited force (gray-zone aggression).
    Probe,
}

impl std::fmt::Display for Action {
    fn fmt(&self, f: &mut std::fmt::Formatter<'"'_>) -> std::fmt::Result {
        match self {
