            Action::Probe => \"Probe\".fmt(f),
        }
    }
}

/// Hidden type of a state: high resolve (WillingToFight = WTF) or low resolve.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ResolveType {
    High, // Willing to fight over the disputed claim
    Low,  // Risk-averse, will concede rather than escalate
}

impl ResolveType {
    pub fn probability_of_backing_down(&self) -> f64 {
        match self {
            ResolveType::High => 0.05, // Almost never backs down
            ResolveType::Low => 0.70,  // High chance of backing down if confronted
        }
    }
}

/// Private information a player holds but does not reveal to others.
#[derive(Debug, Clone)]
