/// Material value of the contested resource/territory.
const RESOURCES_VALUE: f64 = 10.0;

/// Cost of arms expenditure per period.
const ARMS_COST: f64 = -2.5;

/// Cost of fighting a war (scaled by resolve type of both sides).
fn war_cost(attacker_resolve: ResolveType, defender_resolve: ResolveType) -> f64 {
    let attacker_morale = match attacker_resolve {
        ResolveType::High => 0.9,
        ResolveType::Low => 0.4,
    };
    let defender_morale = match defender_resolve {
        ResolveType::High => 0.9,
        ResolveType::Low => 0.4,
    };
    // Winner takes resources minus huge war costs; loser loses resources plus costs.
    (-15.0 * (attacker_morale + defender_morale) / 2.0)
}

/// Payoffs for a single-shot action profile between two players in the cyclic dilemma.
/// Returns (row_player_payoff, col_player_payoff).
pub fn bilateral_payoff(row_action: Action, col_action: Action, row_resolve: ResolveType, col_resolve: ResolveType) -> (f64, f64) {
    let (r_gain, c_gain) = match (row_action, col_action) {
        (Action::Arm, Action::Arm) => {
            // Arms race: both pay cost, no gain → stalemate
            (ARMS_COST, ARMS_COST)
        }
        (Action::Arm, Action::Concede) => {
            // Row arms, col concedes → row wins territory, col loses it
            (RESOURCES_VALUE + ARMS_COST, -RESOURCES_VALUE * 0.5 + ARMS_COST)
        }
        (Action::Arm, Action::Probe) => {
            // Row arms, col probes → war escalates
            let wc = war_cost(row_resolve, col_resolve);
            (wc + 0.5 * RESOURCES_VALUE, wc - 0.5 * RESOURCES_VALUE)
        }
        (Action::Concede, Action::Arm) => {
            let (c, r) = bilateral_payoff(Action::Arm, Action::Concede, col_resolve, row_resolve);
            (r, c)
        }
        (Action::Concede, Action::Concede) => {
            // Mutual concessions: status quo maintained at some cost
            (-0.5, -0.5)
        }
        (Action::Concede, Action::Probe) => {
            // Row concedes, col probes → col gains small advantage without full conflict
            (-(RESOURCES_VALUE * 0.3), RESOURCES_VALUE * 0.3)
        }
        (Action::Probe, Action::Arm) => {
            let (c, r) = bilateral_payoff(Action::Arm, Action::Probe, col_resolve, row_resolve);
            (r, c)
        }
        (Action::Probe, Action::Concede) => {
            let (c, r) = bilateral_payoff(Action::Concede, Action::Probe, col_resolve, row_resolve);
            (r, c)
        }
        (Action::Probe, Action::Probe) => {
            // Both probe: heightened tension, moderate costs
            (-1.5, -1.5)
        }
    };
    (r_gain, c_gain)
}

