/// Observable proxy categories for ceasefire assessment.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ProxyObservables {
    /// AIS ship-density change in disputed maritime zones (% change from baseline).
    pub ais_ship_density_delta: f64,

    /// Nighttime-lights radiance change in border/military regions (W/m²/sr).
    pub ntl_radiance_delta: f64,

    /// News-sentiment score change (positive = more peaceful framing; range [-1, 1]).
    pub news_sentiment_delta: f64,
}

/// Classify whether observed changes indicate real de-escalation or pause-to-rearm.
pub fn classify_ceasefire(obs: &ProxyObservables) -> Classification {
    let deesc_score = compute_deescalation_score(obs);
    let rearm_score = compute_rearm_probability(obs);

    Classification {
        deescalation_probability: deesc_score,
        rearm_probability: rearm_score,
        confidence: 1.0 - (deesc_score - rearm_score).abs(),
        classification: if deesc_score >= rearm_score {
            CeasefireVerdict::RealDeescalation
        } else {
            CeasefireVerdict::PauseToRearm
        },
        explanation: generate_explanation(obs, deesc_score, rearm_score),
    }
}

/// Score capturing how well observables co-move under the de-escalation hypothesis.
/// Under REAL DEESCALATION: all three move consistently toward peaceful indicators.
fn compute_deescalation_score(obs: &ProxyObservables) -> f64 {
    // De-escalation hypothesis predicts:
    //   AIS: military/combat vessels decrease → negative delta (commercial normalizes)
    //   NTL: military light activity decreases → slightly negative or stable
    //   NEWS: sentiment improves significantly → positive delta

    let ais_signal = if obs.ais_ship_density_delta < -0.1 { 1.0 } else { 0.3 };
    let ntl_signal = if obs.ntl_radiance_delta < 0.05 { 1.0 } else { 0.3 };
    let news_signal = if obs.news_sentiment_delta > 0.1 { 1.0 } else { 0.3 };

    // Weighted average — military comms (AIS) gets highest weight since
    // hardest to fake; commercial shipping stays constant so delta reveals
    // military vessel movements most clearly.
    0.40 * ais_signal + 0.30 * ntl_signal + 0.30 * news_signal
}

/// Score capturing how well observables co-move under the pause-to-rearm hypothesis.
/// Under PAUSE-TO-REARM: contradictory patterns emerge.
fn compute_rearm_probability(obs: &ProxyObservables) -> f64 {
    // Re-arm prediction:
    //   AIS: combat vessels withdrawn publicly BUT logistics/support ships increase
    //        → overall AIS may look flat/slightly negative, masking re-arm
    //   NTL: military bases increase power consumption → positive delta
    //        (night operations, manufacturing, testing)
    //   NEWS: propaganda/sanctimonious rhetoric → sentiment artificially positive

    // The key discriminator: NTL goes UP while NEWS looks good
    let contradiction_index = if obs.ntl_radiance_delta > 0.1 && obs.news_sentiment_delta > 0.15 {
        1.0  // Clear contradiction: lights up but rhetoric claims peace
    } else if obs.ntl_radiance_delta > 0.05 && obs.news_sentiment_delta > 0.05 {
        0.6  // Moderate contradiction
    } else {
        0.2  // No contradiction detected
    };

    // Secondary: if AIS is near-zero but NTL is rising → hiding movement
    let ais_mask = if obs.ais_ship_density_delta.abs() < 0.05 && obs.ntl_radiance_delta > 0.1 {
        1.0
    } else if obs.ais_ship_density_delta < 0.0 {
        0.5  // AIS decreasing could be genuine de-esc
    } else {
        0.2
    };

    0.55 * contradiction_index + 0.45 * ais_mask
}

