    let mut parts = vec"'![];

    // AIS interpretation
    if obs.ais_ship_density_delta < -0.15 {
        parts.push(format!("Military vessel presence decreased ({:.1}% drop), consistent with real pullback", obs.ais_ship_density_delta * 100.0));
    } else if obs.ais_ship_density_delta.abs() < 0.05 {
