        parts.push(format"'!("Military/commercial traffic increased ({:.1}%), contradicting ceasefire claims", obs.ais_ship_density_delta * 100.0));
    }

    // NTL interpretation
    if obs.ntl_radiance_delta > 0.15 {
        parts.push(format!("Nightlight radiance surged ({:.1}%), suggesting expanded military activity despite ceasefire", obs.ntl_radiance_delta * 100.0));
    } else if obs.ntl_radiance_delta > 0.05 {
        parts.push(format!("Modest nightlight increase ({:.1}%) — could be routine, or early re-arm signals", obs.ntl_radiance_delta * 100.0));
    } else {
        parts.push(format!("Nightlights stable/down ({:.1}%), consistent with reduced military tempo", obs.ntl_radiance_delta * 100.0));
    }

    // News interpretation
    if obs.news_sentiment_delta > 0.3 {
        parts.push("News sentiment strongly positive — authentic diplomatic progress likely".into());
    } else if obs.news_sentiment_delta > 0.1 {
        parts.push("Moderate positive sentiment — may reflect propaganda or genuine improvement".into());
    } else if obs.news_sentiment_delta > 0.0 {
        parts.push("Weak positive sentiment — insufficient to confirm de-escalation".into());
    } else {
        parts.push("Negative or flat news sentiment undermines ceasefire narrative".into());
    }

    // Cross-check conclusion
    let diff = rearm - deesc;
    if diff > 0.2 {
        parts.push("⚠ HIGH RISK: Multiple proxies co-move under re-arm pattern — ceasefire likely tactical pause".into());
    } else if diff < -0.2 {
        parts.push("✓ LOW RISK: Proxies converge on de-escalation pattern — ceasefire appears genuine".into());
    } else {
        parts.push("◐ AMBIGUOUS: Proxies give mixed signals — extend monitoring window".into());
    }

    parts.join("; ")
}

