        let revealed_types: Vec<ResolveType> = players.iter().map(|p| p.own_resolve).collect();

        for round in 0..rounds {
            let t_cost_per_player = ThirdPartyVerifier::VERIFICATION_COST / 3.0;

            // Players choose optimally knowing true types (post-verification)
            for i in 0..3 {
                let j = (i + 1) % 3;
                let payoff = play_with_verification(
                    players[i].own_resolve, revealed_types[j],
                    t_cost_per_player, &mut rng
                );
                total_trilateral[i] += payoff;
            }
        }

        for i in 0..3 {
            avg_payoffs_trilateral[i] = total_trilateral[i] / rounds as f64;
            if total_trilateral[i] > -0.5 {
                concede_count_trilateral += 1;
            } else {
                arm_count_trilateral += 1;
            }
        }
    }

    SimulationResults {
        n_simulations,
        avg_payoff_bilateral: avg_payoffs_bilateral,
        avg_payoff_trilateral: avg_payoffs_trilateral,
        arm_rate_bilateral: arm_count_bilateral as f64 / (n_simulations as f64 * 3.0),
        concede_rate_bilateral: concede_count_bilateral as f64 / (n_simulations as f64 * 3.0),
        arm_rate_trilateral: arm_count_trilateral as f64 / (n_simulations as f64 * 3.0),
        concede_rate_trilateral: concede_count_trilateral as f64 / (n_simulations as f64 * 3.0),
    }
}

/// Play one bilateral round under incomplete information.
fn play_bilateral_round(
    p1: &PlayerInfo,
    p2: &PlayerInfo,
    rng: &mut impl Rng,
) -> (f64, f64) {
    // Both estimate expected utility of each action
    let u_arm = estimated_u_arm(p1, p2) + p1.own_resolve.probability_of_backing_down() * 0.3;
    let u_concede = -0.5; // Safe fallback
    let u_probe = estimated_u_probe(p1, p2) * 0.5; // Probing risky

    let a1 = choose_best_action(u_arm, u_concede, u_probe, rng);
    let u_arm_j = estimated_u_arm(p2, p1) + p2.own_resolve.probability_of_backing_down() * 0.3;
    let u_concede_j = -0.5;
    let u_probe_j = estimated_u_probe(p2, p1) * 0.5;
    let a2 = choose_best_action(u_arm_j, u_concede_j, u_probe_j, rng);

    bilateral_payoff(a1, a2, p1.own_resolve, p2.own_resolve)
}

fn estimated_u_arm(p_self: &PlayerInfo, p_other: &PlayerInfo) -> f64 {
    // Probability other is Low-type (and will back down) × big gain
    // Probability other is High-type × war risk
    let other_is_low = 1.0 - p_other.belief_b_high;
    other_is_low * (RESOURCES_VALUE + ARMS_COST) + p_other.belief_b_high * war_cost(p_self.own_resolve, ResolveType::High)
}

fn estimated_u_probe(p_self: &PlayerInfo, p_other: &PlayerInfo) -> f64 {
    // Probe only makes sense if other is likely Low-type
    let other_is_low = 1.0 - p_other.belief_b_high;
    other_is_low * RESOURCES_VALUE * 0.3 - (1.0 - other_is_low) * 5.0
}

fn choose_best_action(u_arm: f64, u_concede: f64, u_probe: f64, rng: &mut impl Rng) -> Action {
    let values = [u_arm, u_concede, u_probe];
    let max_val = values.iter().cloned().fold(f64::NEG_INFINITY, f64::max);

    // Softmax selection (temperature = 1.0)
    let exp_sum: f64 = values.iter().map(|v| (v * 2.0).exp()).sum::<f64>();
    let probs: Vec<f64> = values.iter().map(|v| (v * 2.0).exp() / exp_sum).collect();

    let roll = rng.gen_range(0.0..1.0);
    let mut cumulative = 0.0;
    for (i, &prob) in probs.iter().enumerate() {
        cumulative += prob;
        if roll <= cumulative {
            return [Action::Arm, Action::Concede, Action::Probe][i];
        }
    }
    Action::Arm
}

fn update_beliefs(p1: &mut PlayerInfo, p2: &mut PlayerInfo, p2_payoff: f64) {
    // Bayesian update: if opponent took a very aggressive action, they'"'re likely High-type
    if p2_payoff > 2.0 {
        // Opponent gained a lot — likely High resolve
        p1.belief_b_high = (p1.belief_b_high * 1.5).min(0.95);
    } else if p2_payoff < -2.0 {
        // Opponent lost badly — likely got bluffed or is Low
        p1.belief_b_high = (p1.belief_b_high * 0.5).max(0.1);
    }
}

/// Play one round with third-party verification active.
fn play_with_verification(
    my_resolve: ResolveType,
    their_resolve: ResolveType,
    verification_cost: f64,
    _rng: &mut impl Rng,
) -> f64 {
    // With known types, coordinate optimally
    if my_resolve == ResolveType::High && their_resolve == ResolveType::Low {
        // I'm strong, they're weak: negotiate favorable terms
        3.0 - verification_cost
    } else if my_resolve == ResolveType::Low && their_resolve == ResolveType::High {
        // I'm weak, they're strong: accept unfavorable but avoid war
        1.0 - verification_cost
    } else if my_resolve == ResolveType::Low && their_resolve == ResolveType::Low {
        // Both weak: cooperate aggressively, save arms costs
        (-0.5 - verification_cost * 0.5)
    } else {
        // Both strong: cautious cooperation
        (-1.0 - verification_cost * 0.3)
    }
}

