pub fn bil_pay(ra:Action,ca:Action,rr:RType,cr:RType)->(f64,f64){
let(vr,vc)=match(ra,ca){
(Action::Arm,Action::Arm)=>(AC,AC),
(Action::Arm,Action::Concede)=>(RV+AC,-RV*0.5+AC),
(Action::Arm,Action::Probe)=>let w=war_c(rr,cr);(w+0.5*RV,w-0.5*RV),
(Action::Concede,Action::Arm)=>bil_pay(ca,ra,cr,rr).0,bil_pay(ca,ra,cr,rr).1,
(Action::Concede,Action::Concede)=>(-0.5,-0.5),
(Action::Concede,Action::Probe)=>(-(RV*0.3),RV*0.3),
(Action::Probe,Action::Arm)=>bil_pay(ca,ra,cr,rr).0,bil_pay(ca,ra,cr,rr).1,
(Action::Probe,Action::Concede)=>(RV*0.3,-RV*0.3),
(Action::Probe,Action::Probe)=>(-1.5,-1.5),};(vr,vc)}
fn est_u_arm(pi:&PInfo,pj:&PInfo)->f64{let il=1.0-pi.b_nh;il*(RV+AC)+pi.b_nh*war_c(pi.own,RType::High)}
fn est_u_probe(pi:&PInfo,pj:&PInfo)->f64{let il=1.0-pi.b_nh;il*RV*0.3-(1.0-il)*5.0}
fn pick(a:f64,c:f64,p:f64,r:&mut impl Rng)->Action{let v=[a,c,p];let es:f64=v.iter().map(|x|(x*2.0).exp()).sum::<f64>();let pr:v=f64=v.iter().map(|x|(x*2.0).exp()/es).collect();let roll=r.gen_range(0.0..1.0);let mut cum=0.0;for(i,pr_)in pr.iter().enumerate(){cum+=pr_;if roll<=cum{return[i==0]{Action::Arm,i==1}{Action::Concede,Action::Probe}[i]}}Action::Arm}
